-- =====================================================
-- ProductManager
-- Modelo Físico do Banco de Dados
-- SGBD: PostgreSQL
-- =====================================================

-- Criação da tabela de produtos
CREATE TABLE "Products" (

    "Id" INTEGER GENERATED BY DEFAULT AS IDENTITY,

    "Name" VARCHAR(150) NOT NULL,

    "Description" VARCHAR(500),

    "SKU" VARCHAR(50) NOT NULL,

    "CostPrice" DECIMAL(12,2) NOT NULL,

    "SalePrice" DECIMAL(12,2) NOT NULL,

    "Quantity" INTEGER NOT NULL,

    "CreatedAt" TIMESTAMP WITHOUT TIME ZONE
        NOT NULL DEFAULT CURRENT_TIMESTAMP,

    -- Chave primária
    CONSTRAINT "PK_Products"
        PRIMARY KEY ("Id"),

    -- Restrições de valores
    CONSTRAINT "CK_Products_CostPrice"
        CHECK ("CostPrice" >= 0),

    CONSTRAINT "CK_Products_SalePrice"
        CHECK ("SalePrice" > 0),

    CONSTRAINT "CK_Products_Quantity"
        CHECK ("Quantity" >= 0)

);

-- Índice para impedir SKU duplicado,
-- desconsiderando letras maiúsculas e minúsculas.
CREATE UNIQUE INDEX "IX_Products_SKU_CaseInsensitive"
ON "Products" (LOWER("SKU"));

-- Índice para auxiliar pesquisas por nome.
CREATE INDEX "IX_Products_Name"
ON "Products" ("Name");